def is_maximal_triangle_free(edges, n):
    adj = {i: set() for i in range(n)}
    for i in range(0, len(edges), 2):
        u, v = edges[i], edges[i+1]
        adj[u].add(v)
        adj[v].add(u)

    # Check triangle free
    for u in range(n):
        for v in adj[u]:
            if adj[u].intersection(adj[v]):
                return False

    # Check maximal
    for u in range(n):
        for v in range(u+1, n):
            if v not in adj[u]:
                if not adj[u].intersection(adj[v]):
                    return False
    return True

